entries[66103] = { ["name"] = "Pläne: Pyriumwaffenkette", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (500)\nBenutzen: Lehrt Euch die Herstellung einer Pyriumkette.\n\nPyriumwaffenkette\nWird beim Anlegen gebunden\nBenötigt Stufe 81\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euren Trefferwert um 40 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen der Waffenkette wird der Gegenstand seelengebunden.\nBenötigt Pyriumbarren" }
